# frozen_string_literal: true

module Pbt
  module Arbitrary
    # Generates arrays of values generated by `value_arb` with type `T`.
    class ArrayArbitrary < Arbitrary
      DEFAULT_MAX_SIZE = 10
      private_constant :DEFAULT_MAX_SIZE

      # @param value_arb [Arbitrary] Arbitrary to generate values.
      # @param min_length [Integer] Minimum length of the generated array. Default is 0.
      # @param max_length [Integer] Maximum length of the generated array. Default is 10.
      def initialize(value_arb, min_length = 0, max_length = DEFAULT_MAX_SIZE)
        raise ArgumentError, "min_length must be zero or positive number" if min_length < 0

        @min_length = min_length
        @max_length = max_length
        @value_arb = value_arb
        @length_arb = IntegerArbitrary.new(min_length, max_length)
      end

      # @see Arbitrary#generate
      def generate(rng = Random.new)
        length = @length_arb.generate(rng)
        length.times.map { @value_arb.generate(rng) }
      end

      def contextual?
        Sample.contextual?(@value_arb)
      end

      def sample(rng = Random.new)
        samples = Array.new(@length_arb.generate(rng)) { Sample.capture(@value_arb, rng) }
        Sample.array(samples, @length_arb, @min_length)
      end

      # @see Arbitrary#cover?
      def cover?(value)
        return false unless value.is_a?(Array)
        return false if value.size < @min_length
        return false if !@max_length.nil? && value.size > @max_length

        unknown = false
        value.each do |item|
          covered = Arbitrary.cover_result(@value_arb, item)
          return false if covered == false

          unknown = true if covered.nil?
        end
        unknown ? nil : true
      end

      # @see Arbitrary#shrink
      def shrink(current)
        Enumerator.new do |y|
          if current.size > @min_length
            # First, shrink the length of the array via contiguous slices.
            emitted_n_minus_1 = false
            @length_arb.shrink(current.size).each do |length|
              emitted_n_minus_1 = true if length == current.size - 1
              if length == 0
                y.yield []
                next
              end
              current.each_cons(length) do |con|
                y.yield con
              end
            end

            # Second, try deleting individual elements (including non-contiguous interior elements).
            if current.size >= 3
              indices = emitted_n_minus_1 ? (1...(current.size - 1)) : (0...current.size)
              indices.each do |i|
                y.yield [*current[...i], *current[i + 1..]]
              end
            end
          end

          # Third, shrink each element of the array (even when already at min_length).
          current.each_with_index do |item, i|
            @value_arb.shrink(item).each do |val|
              y.yield [*current[...i], val, *current[i + 1..]]
            end
          end
        end
      end
    end
  end
end
